import yaml from "js-yaml";

export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout: string;
  [key: string]: unknown;
}

export interface ParsedDocument {
  data: Frontmatter;
  content: string;
}

const FM_RE = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;

function toDate(value: unknown): Date | null {
  if (value instanceof Date) return value;
  if (typeof value === "string" || typeof value === "number") {
    const d = new Date(value);
    if (!Number.isNaN(d.getTime())) return d;
  }
  return null;
}

function toTags(value: unknown): string[] {
  if (Array.isArray(value)) return value.map(String);
  if (typeof value === "string") {
    return value
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
  }
  return [];
}

/** Parse a Markdown document with optional YAML frontmatter delimited by `---`. */
export function parseFrontmatter(source: string): ParsedDocument {
  let raw: Record<string, unknown> = {};
  let content = source;

  const match = FM_RE.exec(source);
  if (match) {
    const parsed = yaml.load(match[1] ?? "");
    if (parsed !== null && typeof parsed === "object" && !Array.isArray(parsed)) {
      raw = parsed as Record<string, unknown>;
    } else if (parsed != null) {
      throw new Error("Frontmatter must be a YAML mapping");
    }
    content = source.slice(match[0].length);
  }

  const data: Frontmatter = {
    ...raw,
    title: typeof raw.title === "string" ? raw.title : "",
    date: toDate(raw.date),
    tags: toTags(raw.tags),
    draft: raw.draft === true,
    layout: typeof raw.layout === "string" ? raw.layout : "default",
  };

  return { data, content };
}

import MarkdownIt from "markdown-it";
import hljs from "highlight.js";

const md: MarkdownIt = new MarkdownIt({
  html: true,
  linkify: true,
  typographer: true,
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      const { value } = hljs.highlight(code, { language: lang, ignoreIllegals: true });
      return `<pre><code class="hljs language-${lang}">${value}</code></pre>`;
    }
    return `<pre><code class="hljs">${md.utils.escapeHtml(code)}</code></pre>`;
  },
});

/** Render Markdown (frontmatter already stripped) to HTML with syntax highlighting. */
export function renderMarkdown(source: string): string {
  return md.render(source);
}

import Handlebars from "handlebars";
import { promises as fs } from "node:fs";
import path from "node:path";

export interface TemplateEngine {
  /** Render `content` inside the named layout with the given context. */
  renderPage(layout: string, context: Record<string, unknown>): string;
  hasLayout(layout: string): boolean;
}

async function readDirTemplates(dir: string): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  let entries: string[] = [];
  try {
    entries = await fs.readdir(dir);
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (!/\.(hbs|handlebars|html)$/.test(entry)) continue;
    const name = entry.replace(/\.(hbs|handlebars|html)$/, "");
    out.set(name, await fs.readFile(path.join(dir, entry), "utf8"));
  }
  return out;
}

/**
 * Load a template directory:
 *   templates/layouts/*.hbs   -> page layouts (must render `{{{content}}}` somewhere)
 *   templates/partials/*.hbs  -> registered as Handlebars partials by filename
 * Layout files directly in the templates root are also accepted as layouts.
 */
export async function loadTemplates(templateDir: string): Promise<TemplateEngine> {
  const hb = Handlebars.create();

  hb.registerHelper("formatDate", (date: unknown, format?: unknown) => {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
    if (format === "rfc822") return date.toUTCString();
    return date.toISOString().slice(0, 10);
  });
  hb.registerHelper("eq", (a: unknown, b: unknown) => a === b);

  const partials = await readDirTemplates(path.join(templateDir, "partials"));
  for (const [name, src] of partials) hb.registerPartial(name, src);

  const layoutSources = new Map<string, string>([
    ...(await readDirTemplates(templateDir)),
    ...(await readDirTemplates(path.join(templateDir, "layouts"))),
  ]);

  const compiled = new Map<string, Handlebars.TemplateDelegate>();
  for (const [name, src] of layoutSources) {
    compiled.set(name, hb.compile(src, { noEscape: false }));
  }

  return {
    hasLayout: (layout) => compiled.has(layout),
    renderPage(layout, context) {
      const template = compiled.get(layout) ?? compiled.get("default");
      if (!template) {
        throw new Error(
          `No layout "${layout}" and no "default" layout found in ${templateDir}`
        );
      }
      return template(context);
    },
  };
}

import type { Page } from "./build.js";

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export interface RssOptions {
  title: string;
  url: string; // site base URL, no trailing slash required
  description?: string;
  limit?: number;
}

/** Generate an RSS 2.0 feed from pages (drafts already excluded). */
export function generateRss(pages: Page[], opts: RssOptions): string {
  const base = opts.url.replace(/\/+$/, "");
  const items = [...pages]
    .sort((a, b) => (b.data.date?.getTime() ?? 0) - (a.data.date?.getTime() ?? 0))
    .slice(0, opts.limit ?? 20)
    .map((p) => {
      const link = `${base}${p.urlPath}`;
      const date = p.data.date ? `<pubDate>${p.data.date.toUTCString()}</pubDate>` : "";
      const cats = p.data.tags.map((t) => `<category>${esc(t)}</category>`).join("");
      return [
        "    <item>",
        `      <title>${esc(p.data.title)}</title>`,
        `      <link>${esc(link)}</link>`,
        `      <guid isPermaLink="true">${esc(link)}</guid>`,
        date ? `      ${date}` : "",
        cats ? `      ${cats}` : "",
        `      <description>${esc(p.html)}</description>`,
        "    </item>",
      ]
        .filter(Boolean)
        .join("\n");
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${esc(opts.title)}</title>
    <link>${esc(base)}</link>
    <description>${esc(opts.description ?? opts.title)}</description>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>
`;
}

import { promises as fs } from "node:fs";
import path from "node:path";
import { parseFrontmatter, type Frontmatter } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { loadTemplates } from "./templates.js";
import { generateRss } from "./rss.js";

export interface BuildOptions {
  source: string;
  templates: string;
  output: string;
  includeDrafts?: boolean;
  siteTitle?: string;
  siteUrl?: string;
  /** HTML snippet injected before </body> of every page (used by dev server). */
  injectHtml?: string;
}

export interface Page {
  /** Source path relative to source dir, e.g. "posts/hello.md" */
  sourcePath: string;
  /** Output path relative to output dir, e.g. "posts/hello/index.html" */
  outputPath: string;
  /** Site-absolute URL path, e.g. "/posts/hello/" */
  urlPath: string;
  data: Frontmatter;
  html: string;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[]; // tag names that got index pages
  skippedDrafts: number;
  written: string[]; // output-relative paths written
}

async function walk(dir: string, base = dir): Promise<string[]> {
  const out: string[] = [];
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(abs, base)));
    else out.push(path.relative(base, abs));
  }
  return out;
}

function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function toOutputPath(relSource: string): { outputPath: string; urlPath: string } {
  const noExt = relSource.replace(/\.(md|markdown)$/i, "");
  const parts = noExt.split(path.sep);
  if (parts[parts.length - 1] === "index") parts.pop();
  const urlPath = parts.length ? `/${parts.join("/")}/` : "/";
  const outputPath = path.join(...parts, "index.html");
  return { outputPath, urlPath };
}

function injectBeforeBodyClose(html: string, snippet: string): string {
  const idx = html.lastIndexOf("</body>");
  if (idx === -1) return html + snippet;
  return html.slice(0, idx) + snippet + html.slice(idx);
}

export async function build(opts: BuildOptions): Promise<BuildResult> {
  const engine = await loadTemplates(opts.templates);
  const files = await walk(opts.source);
  const written: string[] = [];
  const pages: Page[] = [];
  let skippedDrafts = 0;

  await fs.rm(opts.output, { recursive: true, force: true });
  await fs.mkdir(opts.output, { recursive: true });

  const writeOut = async (rel: string, contents: string | Buffer) => {
    const abs = path.join(opts.output, rel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await fs.writeFile(abs, contents);
    written.push(rel.split(path.sep).join("/"));
  };

  // 1. Parse all markdown files; copy everything else through verbatim.
  for (const rel of files) {
    if (!/\.(md|markdown)$/i.test(rel)) {
      await writeOut(rel, await fs.readFile(path.join(opts.source, rel)));
      continue;
    }
    const raw = await fs.readFile(path.join(opts.source, rel), "utf8");
    const { data, content } = parseFrontmatter(raw);
    if (data.draft && !opts.includeDrafts) {
      skippedDrafts++;
      continue;
    }
    const { outputPath, urlPath } = toOutputPath(rel);
    pages.push({
      sourcePath: rel.split(path.sep).join("/"),
      outputPath,
      urlPath,
      data,
      html: renderMarkdown(content),
    });
  }

  pages.sort((a, b) => (b.data.date?.getTime() ?? 0) - (a.data.date?.getTime() ?? 0));

  const site = {
    title: opts.siteTitle ?? "Site",
    url: (opts.siteUrl ?? "").replace(/\/+$/, ""),
  };
  const pageContext = (p: Page) => ({
    ...p.data,
    content: p.html,
    url: p.urlPath,
    site,
    pages: pages.map((q) => ({ ...q.data, url: q.urlPath })),
  });

  // 2. Render pages through their layout.
  for (const p of pages) {
    let html = engine.renderPage(p.data.layout, pageContext(p));
    if (opts.injectHtml) html = injectBeforeBodyClose(html, opts.injectHtml);
    await writeOut(p.outputPath, html);
  }

  // 3. Tag index pages at /tags/<slug>/.
  const byTag = new Map<string, Page[]>();
  for (const p of pages) {
    for (const tag of p.data.tags) {
      const list = byTag.get(tag) ?? [];
      list.push(p);
      byTag.set(tag, list);
    }
  }
  const tagLayout = engine.hasLayout("tag") ? "tag" : "default";
  for (const [tag, tagged] of byTag) {
    const context = {
      title: `Tag: ${tag}`,
      tag,
      date: null,
      tags: [],
      draft: false,
      layout: tagLayout,
      site,
      content: "",
      url: `/tags/${slugify(tag)}/`,
      pages: tagged.map((q) => ({ ...q.data, url: q.urlPath })),
    };
    let html = engine.renderPage(tagLayout, context);
    if (opts.injectHtml) html = injectBeforeBodyClose(html, opts.injectHtml);
    await writeOut(path.join("tags", slugify(tag), "index.html"), html);
  }

  // 4. RSS feed.
  await writeOut(
    "feed.xml",
    generateRss(pages, { title: site.title, url: site.url || "http://localhost" })
  );

  return { pages, tagPages: [...byTag.keys()], skippedDrafts, written };
}

import http from "node:http";
import { promises as fs } from "node:fs";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { build, type BuildOptions } from "./build.js";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff2": "font/woff2",
};

export function reloadScript(port: number): string {
  return `\n<script>
(() => {
  const connect = () => {
    const ws = new WebSocket("ws://" + location.hostname + ":${port}/__livereload");
    ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
    ws.onclose = () => setTimeout(connect, 1000);
  };
  connect();
})();
</script>\n`;
}

export interface ServeOptions extends BuildOptions {
  port: number;
}

export interface DevServer {
  close(): Promise<void>;
  port: number;
}

export async function serve(opts: ServeOptions): Promise<DevServer> {
  const buildOpts: BuildOptions = { ...opts, injectHtml: reloadScript(opts.port) };
  await build(buildOpts);

  const server = http.createServer(async (req, res) => {
    try {
      const urlPath = decodeURIComponent((req.url ?? "/").split("?")[0] ?? "/");
      let rel = path.normalize(urlPath).replace(/^([/\\]|\.\.)+/, "");
      let abs = path.join(opts.output, rel);
      const stat = await fs.stat(abs).catch(() => null);
      if (stat?.isDirectory() || urlPath.endsWith("/")) abs = path.join(abs, "index.html");
      const body = await fs.readFile(abs);
      res.writeHead(200, {
        "Content-Type": MIME[path.extname(abs)] ?? "application/octet-stream",
        "Cache-Control": "no-store",
      });
      res.end(body);
    } catch {
      res.writeHead(404, { "Content-Type": "text/plain" });
      res.end("Not Found");
    }
  });

  const wss = new WebSocketServer({ server, path: "/__livereload" });
  const broadcast = (msg: string) => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  let pending: NodeJS.Timeout | null = null;
  const rebuild = () => {
    if (pending) clearTimeout(pending);
    pending = setTimeout(async () => {
      try {
        await build(buildOpts);
        broadcast("reload");
        console.log("[ssg] rebuilt, reload sent");
      } catch (err) {
        console.error("[ssg] rebuild failed:", err);
      }
    }, 100);
  };

  const watcher = chokidar.watch([opts.source, opts.templates], {
    ignoreInitial: true,
  });
  watcher.on("all", rebuild);

  await new Promise<void>((resolve) => server.listen(opts.port, resolve));
  console.log(`[ssg] dev server at http://localhost:${opts.port}/ (live reload enabled)`);

  return {
    port: opts.port,
    async close() {
      if (pending) clearTimeout(pending);
      await watcher.close();
      for (const client of wss.clients) client.terminate();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve()))
      );
    },
  };
}

#!/usr/bin/env node
import { fileURLToPath } from "node:url";
import { build } from "./build.js";
import { serve } from "./server.js";

export interface CliOptions {
  command: "build" | "serve";
  source: string;
  templates: string;
  output: string;
  drafts: boolean;
  port: number;
  siteTitle: string;
  siteUrl: string;
  help: boolean;
}

export const HELP = `ssg - static site generator

Usage:
  ssg build [options]   Build the site once
  ssg serve [options]   Build, serve, and rebuild on changes (live reload)

Options:
  -s, --source <dir>      Markdown source directory      (default: content)
  -t, --templates <dir>   Handlebars template directory  (default: templates)
  -o, --output <dir>      Output directory               (default: dist-site)
  -d, --drafts            Include draft: true pages
  -p, --port <n>          Dev server port                (default: 3000)
      --site-title <s>    Site title (templates + RSS)   (default: Site)
      --site-url <url>    Absolute site URL for RSS      (default: http://localhost)
  -h, --help              Show this help
`;

export class CliError extends Error {}

/** Parse argv (without the leading node/script entries) into CLI options. */
export function parseArgs(argv: string[]): CliOptions {
  const opts: CliOptions = {
    command: "build",
    source: "content",
    templates: "templates",
    output: "dist-site",
    drafts: false,
    port: 3000,
    siteTitle: "Site",
    siteUrl: "http://localhost",
    help: false,
  };

  const args = [...argv];
  const first = args[0];
  if (first === "build" || first === "serve") {
    opts.command = first;
    args.shift();
  } else if (first && !first.startsWith("-")) {
    throw new CliError(`Unknown command: ${first}`);
  }

  const takeValue = (flag: string): string => {
    const v = args.shift();
    if (v === undefined || v.startsWith("-")) {
      throw new CliError(`Missing value for ${flag}`);
    }
    return v;
  };

  while (args.length) {
    const arg = args.shift()!;
    switch (arg) {
      case "-s":
      case "--source":
        opts.source = takeValue(arg);
        break;
      case "-t":
      case "--templates":
        opts.templates = takeValue(arg);
        break;
      case "-o":
      case "--output":
        opts.output = takeValue(arg);
        break;
      case "-d":
      case "--drafts":
        opts.drafts = true;
        break;
      case "-p":
      case "--port": {
        const n = Number(takeValue(arg));
        if (!Number.isInteger(n) || n < 0 || n > 65535) {
          throw new CliError(`Invalid port: ${n}`);
        }
        opts.port = n;
        break;
      }
      case "--site-title":
        opts.siteTitle = takeValue(arg);
        break;
      case "--site-url":
        opts.siteUrl = takeValue(arg);
        break;
      case "-h":
      case "--help":
        opts.help = true;
        break;
      default:
        throw new CliError(`Unknown option: ${arg}`);
    }
  }
  return opts;
}

export async function main(argv: string[]): Promise<number> {
  let opts: CliOptions;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    if (err instanceof CliError) {
      console.error(`Error: ${err.message}\n\n${HELP}`);
      return 2;
    }
    throw err;
  }

  if (opts.help) {
    console.log(HELP);
    return 0;
  }

  const shared = {
    source: opts.source,
    templates: opts.templates,
    output: opts.output,
    includeDrafts: opts.drafts,
    siteTitle: opts.siteTitle,
    siteUrl: opts.siteUrl,
  };

  if (opts.command === "serve") {
    await serve({ ...shared, port: opts.port });
    return 0; // keeps running; server holds the event loop
  }

  const result = await build(shared);
  console.log(
    `Built ${result.pages.length} page(s), ${result.tagPages.length} tag page(s), ` +
      `feed.xml (${result.skippedDrafts} draft(s) skipped) -> ${opts.output}`
  );
  return 0;
}

const isDirectRun =
  process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isDirectRun) {
  main(process.argv.slice(2)).then(
    (code) => {
      if (code !== 0) process.exitCode = code;
    },
    (err) => {
      console.error(err instanceof Error ? err.message : err);
      process.exitCode = 1;
    }
  );
}

export { parseFrontmatter, type Frontmatter, type ParsedDocument } from "./frontmatter.js";
export { renderMarkdown } from "./markdown.js";
export { loadTemplates, type TemplateEngine } from "./templates.js";
export { build, type BuildOptions, type BuildResult, type Page } from "./build.js";
export { generateRss, type RssOptions } from "./rss.js";
export { serve, reloadScript, type ServeOptions, type DevServer } from "./server.js";
export { parseArgs, main, CliError, HELP, type CliOptions } from "./cli.js";

