import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";

export interface Fixture {
  root: string;
  source: string;
  templates: string;
  output: string;
  cleanup(): Promise<void>;
}

const DEFAULT_LAYOUT = `<!DOCTYPE html>
<html>
<head><title>{{title}} - {{site.title}}</title></head>
<body>
{{> header}}
<main>{{{content}}}</main>
</body>
</html>`;

const TAG_LAYOUT = `<!DOCTYPE html>
<html>
<head><title>{{title}}</title></head>
<body>
<h1>{{tag}}</h1>
<ul>{{#each pages}}<li><a href="{{url}}">{{title}}</a></li>{{/each}}</ul>
</body>
</html>`;

const HEADER_PARTIAL = `<header class="site-header">{{site.title}}</header>`;

/** Create a temp site with default templates; add content via `files`. */
export async function makeFixture(files: Record<string, string> = {}): Promise<Fixture> {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "ssg-test-"));
  const source = path.join(root, "content");
  const templates = path.join(root, "templates");
  const output = path.join(root, "out");

  await fs.mkdir(path.join(templates, "layouts"), { recursive: true });
  await fs.mkdir(path.join(templates, "partials"), { recursive: true });
  await fs.mkdir(source, { recursive: true });

  await fs.writeFile(path.join(templates, "layouts", "default.hbs"), DEFAULT_LAYOUT);
  await fs.writeFile(path.join(templates, "layouts", "tag.hbs"), TAG_LAYOUT);
  await fs.writeFile(path.join(templates, "partials", "header.hbs"), HEADER_PARTIAL);

  for (const [rel, contents] of Object.entries(files)) {
    const abs = path.join(source, rel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await fs.writeFile(abs, contents);
  }

  return {
    root,
    source,
    templates,
    output,
    cleanup: () => fs.rm(root, { recursive: true, force: true }),
  };
}

export const POST = (
  title: string,
  extra: Record<string, string | boolean> = {},
  body = `# ${title}\n\nHello *world*.`
): string => {
  const lines = [`title: ${title}`];
  for (const [k, v] of Object.entries(extra)) lines.push(`${k}: ${v}`);
  return `---\n${lines.join("\n")}\n---\n\n${body}\n`;
};

import { describe, it, expect } from "vitest";
import { parseFrontmatter } from "../src/frontmatter.js";

describe("parseFrontmatter", () => {
  it("parses title, date, tags, draft, layout", () => {
    const { data, content } = parseFrontmatter(
      `---
title: Hello World
date: 2024-03-15
tags: [ts, web]
draft: true
layout: post
---

Body here.`
    );
    expect(data.title).toBe("Hello World");
    expect(data.date?.toISOString().slice(0, 10)).toBe("2024-03-15");
    expect(data.tags).toEqual(["ts", "web"]);
    expect(data.draft).toBe(true);
    expect(data.layout).toBe("post");
    expect(content.trim()).toBe("Body here.");
  });

  it("applies defaults when frontmatter is absent", () => {
    const { data, content } = parseFrontmatter("Just markdown.");
    expect(data).toMatchObject({ title: "", date: null, tags: [], draft: false, layout: "default" });
    expect(content).toBe("Just markdown.");
  });

  it("applies defaults for missing keys in present frontmatter", () => {
    const { data } = parseFrontmatter("---\ntitle: Only Title\n---\nbody");
    expect(data.tags).toEqual([]);
    expect(data.draft).toBe(false);
    expect(data.date).toBeNull();
  });

  it("accepts comma-separated tags string", () => {
    const { data } = parseFrontmatter("---\ntags: a, b , c\n---\nx");
    expect(data.tags).toEqual(["a", "b", "c"]);
  });

  it("accepts YAML list tags", () => {
    const { data } = parseFrontmatter("---\ntags:\n  - alpha\n  - beta\n---\nx");
    expect(data.tags).toEqual(["alpha", "beta"]);
  });

  it("treats non-boolean draft values as false", () => {
    const { data } = parseFrontmatter('---\ndraft: "yes"\n---\nx');
    expect(data.draft).toBe(false);
  });

  it("ignores invalid dates", () => {
    const { data } = parseFrontmatter("---\ndate: not-a-date\n---\nx");
    expect(data.date).toBeNull();
  });

  it("preserves custom keys", () => {
    const { data } = parseFrontmatter("---\nauthor: Ada\n---\nx");
    expect(data.author).toBe("Ada");
  });

  it("handles CRLF line endings", () => {
    const { data, content } = parseFrontmatter("---\r\ntitle: CRLF\r\n---\r\nbody");
    expect(data.title).toBe("CRLF");
    expect(content).toBe("body");
  });

  it("does not treat a thematic break mid-document as frontmatter", () => {
    const { data, content } = parseFrontmatter("intro\n---\ntitle: nope\n---\n");
    expect(data.title).toBe("");
    expect(content.startsWith("intro")).toBe(true);
  });

  it("throws on non-mapping frontmatter", () => {
    expect(() => parseFrontmatter("---\n- just\n- a list\n---\nx")).toThrow(/mapping/);
  });
});

import { describe, it, expect } from "vitest";
import { renderMarkdown } from "../src/markdown.js";

describe("renderMarkdown", () => {
  it("renders basic markdown", () => {
    const html = renderMarkdown("# Title\n\nSome *emphasis*.");
    expect(html).toContain("<h1>Title</h1>");
    expect(html).toContain("<em>emphasis</em>");
  });

  it("syntax-highlights fenced code blocks with a known language", () => {
    const html = renderMarkdown('```ts\nconst x: number = 1;\n```');
    expect(html).toContain('class="hljs language-ts"');
    expect(html).toMatch(/<span class="hljs-/);
  });

  it("escapes code for unknown languages without highlighting", () => {
    const html = renderMarkdown('```nosuchlang\n<b>&raw</b>\n```');
    expect(html).toContain("&lt;b&gt;&amp;raw&lt;/b&gt;");
    expect(html).not.toContain("language-nosuchlang");
  });

  it("does not double-wrap pre/code", () => {
    const html = renderMarkdown('```js\n1\n```');
    expect(html.match(/<pre>/g)?.length).toBe(1);
    expect(html.match(/<code/g)?.length).toBe(1);
  });
});
